  books.push(['https://www.state.gov/public-schedule/','Public Schedules']);
  books.push(['https://www.state.gov/todays-briefing-schedule/','Briefing Schedule']);
}else if(cat==='countries'){
  var bureauData=[
    {name:'Bureau of African Affairs (AF)',url:'https://www.state.gov/bureau-of-african-affairs-releases/'},
    {name:'Bureau of East Asian and Pacific Affairs (EAP)',url:'https://www.state.gov/bureau-of-east-asian-and-pacific-affairs-releases/'},
    {name:'Bureau of European and Eurasian Affairs (EUR)',url:'https://www.state.gov/bureau-of-european-and-eurasian-affairs-releases/'},
    {name:'Bureau of Near Eastern Affairs (NEA)',url:'https://www.state.gov/bureau-of-near-eastern-affairs-releases/'},
    {name:'Bureau of South and Central Asian Affairs (SCA)',url:'https://www.state.gov/bureau-of-south-and-central-asian-affairs-releases/'},
    {name:'Bureau of Western Hemisphere Affairs (WHA)',url:'https://www.state.gov/bureau-of-western-hemisphere-affairs-releases/'}
  ];
  for(var i=0;i<bureauData.length;i++){books.push([bureauData[i].url,bureauData[i].name]);}
  var seen={};
  var allLinks=doc.select('a[href*="/countries-areas/"],a[href*="/countries-areas-archive/"]');
  for(var j=0;j<allLinks.size();j++){
    var a=allLinks.get(j);
    var href=a.attr('href')||'';
    var name=a.text().trim();
    if(!href||!name)continue;
    if(href.indexOf('list')>=0)continue;
    if(name.length>50)continue;
    if(name==='Countries & Areas')continue;
    if(href.indexOf('http')!==0)href='https://www.state.gov'+href;
    var key=href.toLowerCase();
    if(seen[key])continue;
    seen[key]=true;

    books.push([href,name]);
  }
  books.sort(function(a,b){var na=a[1].toLowerCase(),nb=b[1].toLowerCase();if(na<nb)return -1;if(na>nb)return 1;return 0;});
}else if(cat==='bureaus'){
  var bureauCovers={"d":"https://www.state.gov/wp-content/uploads/2018/10/HP_Hero-Alt_GettyImages-713834891_v1-2560x852.jpg","d-mr":"https://www.state.gov/wp-content/uploads/2018/10/HP_Hero-Alt_GettyImages-713834891_v1-2560x852.jpg","t":"https://www.state.gov/wp-content/uploads/2018/08/Under-Secretary-for-Arms-Control-and-International-Security-Hero-Image-2560x852.jpg","e":"https://www.state.gov/wp-content/uploads/2024/11/HP_Hero-Alt_GettyImages-713834891_v1-e1732142758255-2560x852.jpg","f":"https://www.state.gov/wp-content/uploads/2024/11/HP_Hero-Alt_GettyImages-713834891_v1-e1732142758255.jpg","m":"https://www.state.gov/wp-content/uploads/2018/12/Under-Secretary-for-Management-Hero-Image-2560x852.jpg","p":"https://www.state.gov/wp-content/uploads/2018/08/Under-Secretary-for-Political-Affairs-Hero-Image-2560x852.jpg","r":"https://www.state.gov/wp-content/uploads/2026/02/r-handshake-blue-1024x341.jpg"};
  var targets={
    'd':'Deputy Secretary of State (D)',
    'd-mr':'Deputy Secretary of State for Management and Resources (D-MR)',
    't':'Under Secretary for Arms Control and International Security (T)',
    'e':'Under Secretary for Economic Affairs (E)',
    'f':'Under Secretary for Foreign Assistance, Humanitarian Affairs, and Religious Freedom (F)',
    'm':'Under Secretary for Management (M)',
    'p':'Under Secretary for Political Affairs (P)',
    'r':'Under Secretary for Public Diplomacy and Public Affairs (R)'
  };
  var order=['d','d-mr','t','e','f','m','p','r'];
  for(var oi=0;oi<order.length;oi++){
    var id=order[oi];
    var section=doc.select('#'+id).first();
    if(!section)continue;
    var el=section;
    var mainAdded=false;
    while(true){
      el=el.nextElementSibling();
      if(!el)break;
      var elId=''+el.id();
      if(elId&&targets[elId]!==undefined)break;
      var btns=el.select('.wp-block-button__link');
      for(var k=0;k<btns.size();k++){
        var btn=btns.get(k);
        var href=btn.attr('href')||'';
        var txt=btn.text().trim();
        if(!href||!txt)continue;
        if(href.indexOf('govdelivery.com')>=0||href.indexOf('x.com')>=0||href.indexOf('twitter.com')>=0)continue;
        if(txt.indexOf('Subscribe')===0||txt.indexOf('Follow')===0)continue;
        if(href.indexOf('http')!==0)href='https://www.state.gov'+href;
        if(txt.indexOf('View ')!==0)continue;
        if(!mainAdded){
          var coverImg=section.select("img").first();
          var sectionCover=coverImg?String(coverImg.attr("src")||coverImg.attr("data-src")||coverImg.attr("data-lazy-src")):"";
          books.push([href,targets[id],sectionCover]);
          mainAdded=true;
        }else{
          var subName=txt.replace(/^View\s+/,'');
          books.push([href,targets[id]+' - '+subName]);
        }
      }
    }
  }
}
books;

