ruleToc.nextTocUrl:
a.pages_next@href||div.pages a@href
<js>
try {
    //java.log("ToC:"+book.tocUrl) 
    list = result;

    // 获取 pagerange 并检查是否有效 
    pagerange = book.getVariable("custom"); 
    if (typeof pagerange === 'string' && pagerange.trim()  !== '') {
        startpage = parseInt(pagerange.split(',')[0]); 
        endpage = parseInt(pagerange.split(',')[1]); 
    } else {
        // 如果 pagerange 无效，设置默认值 
        startpage = 2;
        endpage = 15;
    }

    // 检查 startpage 和 endpage 是否为有效数字 
    if (isNaN(startpage) || isNaN(endpage)) {
        startpage = 2;
        endpage = 15;
    }

    //prefix=list[list.length -1].split('page=')[0]
    prefix = book.tocUrl; 

    // 检查 list 是否有效并获取 lastpage 
    if (Array.isArray(list)  && list.length  > 0) {
        lastpage = parseInt(list[list.length - 1].split('page=')[1]);
    } else {
        lastpage = endpage; // 如果 list 无效，使用 endpage 作为 lastpage 
    }

    if (endpage < lastpage) {
        genlist = [];
        for (i = startpage; i <= endpage; i = i + 1) {
            nexturl = prefix + 'page=' + String(i);
            genlist.push(nexturl); 
        }
        out = genlist;
    } else {
        out = list;
    }

    //java.log(out); 
    out;
} catch (e) {
    java.log("An  error occurred: " + e.message); 
    // 返回一个默认值或处理异常的逻辑 
    out = [];
    out;
}
</js>

