function antiBotBody(response) {
    try {
        if (response == null) return "";
        var body = response.body;
        if (body != null && typeof body !== "function") return String(body);
        if (typeof body === "function") return String(body.call(response));
    } catch (e) {}
    return typeof response === "string" ? String(response) : "";
}
function antiBotBlocked(body) {
    var text = String(body || "").toLowerCase();
    var markers = ["cloudflare", "performing security verification", "challenge-platform",
        "verify you are human", "access denied", "errors.edgesuite.net", "akamai"];
    for (var i = 0; i < markers.length; i++) if (text.indexOf(markers[i]) >= 0) return true;
    return false;
}
var antiBotResponse = result;
var antiBotBodyText = antiBotBody(antiBotResponse);
if (antiBotBlocked(antiBotBodyText)) {
    var antiBotUrl = String(java.url || baseUrl || "");
    try { antiBotUrl = decodeURIComponent(antiBotUrl); } catch (e) {}
    if (!/^https?:\/\//i.test(antiBotUrl) || antiBotUrl.indexOf("{{") >= 0) throw "反爬验证地址无效";
