//main[@id="page-content"]
<js>

//正文规则后 or 列表规则之前
TARGET_LANG = 'zh-Hans'; // 目标语言
// 需要移除的选择器
var remove_selector = ["script", "noscript", "style", "div.btn-row.-page-actions", "DIV.social-media-buttons", "DIV.full-bg-sand.full-bg-bottom", "DIV.tabContent", "main aside", "#buybox", "follow-rand"];
var html = String(result);
var Jsoup = org.jsoup.Jsoup;
var doc = Jsoup.parse(html);

// 遍历选择器并移除匹配的元素
remove_selector.forEach(function(css) {
    var elements = doc.select(css); // 选择匹配的元素
    elements.forEach(function(element) {
        element.remove(); // 移除单个元素
        //java.log("Removed element with selector: " + css); // 记录日志
    });
});

// 仅遍历具有 data-src 属性的 img 标签 
doc.select("img[data-src]").forEach(function(img)  {
    var dataSrc = img.attr("data-src"); 
    img.attr("src",  dataSrc); // 将 data-src 的值赋给 src 属性 

    // 使用 Iterator 遍历并删除除 src 以外的所有属性 
    var attributes = img.attributes().iterator(); 
    while (attributes.hasNext())  {
        var attr = attributes.next(); 
        if (attr.getKey()  != "src") {
            attributes.remove();  // 使用 Iterator#remove() 安全删除属性 
        }
    }
});
result = doc.html();
var remove_selector = ["script", "noscript", "style", "div.btn-row.-page-actions", "DIV.social-media-buttons", "DIV.full-bg-sand.full-bg-bottom", "DIV.tabContent", "main aside", "#buybox", "follow-rand"];
var extract_selector = [];
var formula_mode = 'none';
var formula_selector = '';
result = TH(result, java, cache, {remove_selector:["script", "noscript", "style", "div.btn-row.-page-actions", "DIV.social-media-buttons", "DIV.full-bg-sand.full-bg-bottom", "DIV.tabContent", "main aside", "#buybox", "follow-rand"], extract_selector:[], formula_mode:formula_mode, formula_selector:formula_selector});
result;
result;
</js>

