     * @type {object}
     */
    cr.googleTranslate = (function() {
	/**
	 * Error definitions for |errorCode|. See chrome/common/translate_errors.h
	 * to modify the definition.
	 * @const
	 */
	const ERROR = {
            'NONE': 0,
            'INITIALIZATION_ERROR': 2,
            'UNSUPPORTED_LANGUAGE': 4,
            'TRANSLATION_ERROR': 6,
            'TRANSLATION_TIMEOUT': 7,
