		return BAD_REQUEST_ERROR['INVALID_INPUT'];
            case 401:
		return BAD_REQUEST_ERROR['INVALID_CREDENTIALS'];
            case 429:
		return BAD_REQUEST_ERROR['TOO_MANY_REQUESTS'];
