		} else if (errorData.status === SCRIPT_CUSTOM_STATUS_CODE['NETWORK_TIMEOUT']) {
                    edgeScriptResult = EDGE_SCRIPT_RESULT['TIMEOUT'];
		} else if (isBadRequest(errorData)) {
                    edgeScriptResult = EDGE_SCRIPT_RESULT['BAD_REQUEST'];
