		} else if (isServerError(errorData)) {
                    edgeScriptResult = EDGE_SCRIPT_RESULT['SERVICE_ERROR'];
		} else if (errorData.status === 0) {
                    edgeScriptResult = EDGE_SCRIPT_RESULT['NETWORK'];
		}
            } catch (e) {
		edgeScriptResult = EDGE_SCRIPT_RESULT['UNKNOWN'];
            }
