function burl(page1url, result){
// 1. 移除page1url中的`./`并标准化路径 
const basePath = page1url.split('/./')[0];  // 提取基础路径 
const restPath = page1url.split('/./')[1];  // 提取后续路径 

// 2. 拼接并移除多余的`./`和斜杠 
const normalizedBase = `${basePath}/${restPath}`.replace('//', '/');
const ret = `${normalizedBase.split('/').slice(0,  -1).join('/')}/${result.replace('./',  '')}`;
return ret
}

