@css:div#printtext > div.field-text@html
<js>
var TARGET_LANG = 'zh-Hans';

function getAUTHkey(){
  var token = java.ajax("https://edge.microsoft.com/translate/auth");
  if (typeof token === "object" && token.toString) {
    token = token.toString();
  }
  java.put("AUTH", token);
  return token;
}

function translateText(text, targetLang){
  if (!text || !text.trim()) return text;
  var token = java.get("AUTH") || getAUTHkey();
  var body = JSON.stringify([text]);
  var headers = {
    "Authorization": "Bearer " + token,
    "Content-Type": "application/json"
  };
  var option = JSON.stringify({"method": "post", "headers": headers, "body": body});
  var endpoint = "https://edge.microsoft.com/translate/translatetext?to=" + targetLang;
  var resp = java.ajax(endpoint + "," + option);
  if (resp && resp.trim()) {
    var arr = JSON.parse(resp);
    if (arr[0] && arr[0].translations && arr[0].translations[0]) {
      return arr[0].translations[0].text;
    }
  }
  return text;
}

// 修复相对路径
result = result.replace(/src="\/sites\//g, 'src="https://russtrat.ru/sites/');
result = result.replace(/href="\/taxonomy\//g, 'href="https://russtrat.ru/taxonomy/');
result = result.replace(/href="\/analytics\//g, 'href="https://russtrat.ru/analytics/');
result = result.replace(/href="\/news\//g, 'href="https://russtrat.ru/news/');

// 翻译正文 HTML 中的文本节点
var Jsoup = org.jsoup.Jsoup;
var doc = Jsoup.parse(result);
var elements = doc.select("p, h1, h2, h3, h4, h5, h6, li, td, th, span, strong, em");
for (var i = 0; i < elements.size(); i++) {
  var el = elements.get(i);
  var text = el.ownText();
  if (text && text.trim().length > 0) {
    var translated = translateText(text, TARGET_LANG);
    if (translated && translated !== text) {
      var textNodes = el.textNodes();
      for (var j = 0; j < textNodes.size(); j++) {
        var tn = textNodes.get(j);
        if (tn.text().trim() === text.trim()) {
          tn.text(translated);
          break;
        }
      }
    }
  }
}
result = doc.html();
result;
</js>

