        }
        if (!imageSrc) continue;
        try {
            var speech = _ltString(el.attr("data-semantic-speech") || el.text()).replace(/\s+/g, " ").trim();
            var img = doc.createElement("img");
            img.attr("src", imageSrc); img.attr("alt", speech); el.replaceWith(img);
