	 * Translation script returns some custom error codes along with standard
	 * HTTP status code.
	 * @const
	 */
	const SCRIPT_CUSTOM_STATUS_CODE = {
            'NETWORK_TIMEOUT': -1,
            'SCRIPT_TIMEOUT': -2,
	};

