       keep readable speech text, and leave the original formula on failure. */
    var formulas;
    try { formulas = doc.select(selector || "math"); } catch (e) { return; }
    for (var i = 0; i < formulas.size(); i++) {
        var el = formulas.get(i), mathml = _ltString(el.outerHtml());
        if (!mathml) continue;
