result = doc.html();
var remove_selector = ["script", "noscript", "style", "div.btn-row.-page-actions", "main aside", "DIV.ContentItemHtml.discussion-box", "DIV.col-md-3.section2", "DIV.AdSpot"];
var extract_selector = [];
var formula_mode = 'none';
var formula_selector = '';
result = TH(result, java, cache, {remove_selector:["script", "noscript", "style", "div.btn-row.-page-actions", "main aside", "DIV.ContentItemHtml.discussion-box", "DIV.col-md-3.section2", "DIV.AdSpot"], extract_selector:[], formula_mode:formula_mode, formula_selector:formula_selector});
result;
result;
