function prepareContent(html) {

    html = html == null ? "" : String(html);
    var extract_selector = ['.inline-formula','disp-formula'];
var Jsoup = org.jsoup.Jsoup;
var doc = Jsoup.parse(html);

// ---------- 0. ★ 公式转图片：基于DOM读取 webJs 阶段写入的 data-original-tex 属性 ----------
function extractMiText(el){
    var mis = el.select('span.mi');
    if (mis.size() == 0) {
        // disp-formula 因HTML5解析被拆散：MathJax_Display 变成了父<p>的下一个兄弟节点
        var parent = el.parent();
        var sib = parent ? parent.nextElementSibling() : null;
        if (sib && sib.hasClass('MathJax_Display')) {
            mis = sib.select('span.mi');
            sib.remove(); // ★ 提取完文本后必须删除这个孤立的渲染节点，否则会残留一大段无意义的MathJax内部span标记混入正文
        }
    }
    var miText = '';
    for (var j = 0; j < mis.size(); j++){
        var t = String(mis.get(j).text()).trim();
        if (t) miText += (miText ? ' ' : '') + t;
    }
    return miText;
}
function formulaSpeech(tex, java, cache){
    var cacheKey = 'codecogs_speech:' + tex;
    var cached = cache.get(cacheKey);
    if (cached != null) return String(cached);
    try {
        var response = java.ajax('https://latex.codecogs.com/mathml.latex?' + encodeURIComponent(tex));
        var speechDoc = org.jsoup.Jsoup.parse(String(response || ''));
        var speech = String(speechDoc.select('span.cc-speech').text()).trim();
        if (speech) cache.put(cacheKey, speech, 2592000);
        return speech;
    } catch (e) {
        java.log('公式朗读文本获取失败: ' + e);
        return '';
    }
}
function formulaToImage(doc){
    var formulas = doc.select('disp-formula, inline-formula');
    for (var i = 0; i < formulas.size(); i++){
        var el = formulas.get(i);
        try {
            var preview = el.select('tex-math').first();
            var tex = preview ? String(preview.text()).trim() : '';
            if (!tex) {
                var source = el.select('span.tex.tex2jax_ignore').first();
                tex = source ? String(source.text()).trim() : '';
            }
            if (!tex) continue; // 未保留公式源码时，交给下面 extract_selector 兜底转纯文本
            var miText = extractMiText(el);
            var speechText = formulaSpeech(tex, java, cache);
            var imgUrl = 'https://latex.codecogs.com/svg.latex?' + encodeURIComponent(tex);
            var imgEl = doc.createElement('img');
            imgEl.attr('src', imgUrl);
            el.replaceWith(imgEl);
            //java.log("formula:"+tex+"->"+imgUrl)
            if (speechText || miText) {
                var spanEl = doc.createElement('span');
                //spanEl.addClass('notranslate');
                spanEl.text(' ' + (speechText || miText) + ' ');
                imgEl.after(spanEl);
            }
        } catch (e) {
            java.log('公式转图片失败: ' + e);
        }
    }
    // ★ 兜底清理：以防某些 MathJax_Display 没有被上面的 extractMiText 正确摘除
    // (例如结构异常/多层嵌套)，统一在最后再清一遍，避免残留大段MathJax内部渲染标记。
    doc.select('div.MathJax_Display').remove();
}
formulaToImage(doc);

// ---------- 2. 原有清理逻辑（保持）----------
remove_selector && remove_selector.forEach(function(css){      // ★ 修复:原是 remove_selector 未定义会报错
    doc.select(css).forEach(function(el){ el.remove(); });
});

doc.select("a:has(img[loading='lazy'])").forEach(function(element){
    var img = element.select("img").first();
    if (img) {
        var aHref = element.attr("href");
        if (aHref) {
            var src = aHref + ',{"webView":true}';
            img.attr("src", src);
        }
    }
});

doc.select("img[src]").forEach(function(img){
    var attributes = img.attributes().iterator();
    while (attributes.hasNext()) {
        var attr = attributes.next();
        if (attr.getKey() != "src") { attributes.remove(); }
    }
});

function replaceElementsWithText(selectors){
    selectors.forEach(function(selector){
        doc.select(selector).forEach(function(element){
            var clone = element.clone();
            clone.select("script").remove();
            var textNode = new org.jsoup.nodes.TextNode(clone.text().replace(' ',''));
            element.replaceWith(textNode);
        });
    });
}
replaceElementsWithText(extract_selector);

// ---------- 3. 翻译清理后的 HTML 文本节点 ----------
return TC(doc.html(), java, cache);


}

if (result !== "") { result = prepareContent(result); }
result;
