//header//h1|//div[@id="article_sections_menu"]|//section[@id="abstract"]|//section[@id="bodymatter"]
<js>

//正文规则后 or 列表规则之前
TARGET_LANG = 'zh-Hans'; // 目标语言
// 需要移除的选择器
var remove_selector = ["script", "noscript", "style", "div.btn-row.-page-actions", "main aside"];
var html = String(result);
var Jsoup = org.jsoup.Jsoup;
var doc = Jsoup.parse(html);

// 遍历选择器并移除匹配的元素
remove_selector.forEach(function(css) {
    var elements = doc.select(css); // 选择匹配的元素
    elements.forEach(function(element) {
        element.remove(); // 移除单个元素
        //java.log("Removed element with selector: " + css); // 记录日志
    });
});
result = doc.html();
var remove_selector = ["script", "noscript", "style", "div.btn-row.-page-actions", "main aside"];
var extract_selector = [];
var formula_mode = 'none';
var formula_selector = '';
result = TH(result, java, cache, {remove_selector:["script", "noscript", "style", "div.btn-row.-page-actions", "main aside"], extract_selector:[], formula_mode:formula_mode, formula_selector:formula_selector});
result;
result;
</js>

