function waitelement(pattern, millis){
    var date = new Date();
    var curDate = null;
    do { curDate = new Date(); 
        if (document.querySelector(pattern)){
            java.log('find element')
            break
        }
       }
    while(curDate-date < millis );
}
remove_selector=['script',
		 '[role="doc-biblioref"]',
		 'noscript',
		 'style',
		 'nav',
		 'section.denial-block',
		]

if (document.querySelector('#translate-done')){
for (s of document.querySelectorAll('script'))     {
    s.remove();
}
    result = document.body.outerHTML
}else if (!document.querySelector('#translate-start'))
{


    var myspan = document.createElement("span");
    myspan.id = 'translate-start'
    document.body.append(myspan)

    waitelement('div#body',8000)
// wait for new 

    for (css of remove_selector){
	for (element of document.querySelectorAll(css)){
	    element.parentNode.removeChild(element);
	}
    }
ref_selector = 'a[data-xocs-content-type="reference"]'

for (ref of document.querySelectorAll(ref_selector)){

    cont = ref.text.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
    var pattern =  new RegExp(`\([^\)]*`+cont+`[^\(]*\)`, 'g');
    if (pattern.test(ref.parentNode.innerText)){
	ref.remove()
    }
}
