    var kids = node.children();
    var n = kids.size();
    var text = String(node.text()).trim();
    function kid(i) { return i < n ? mathSpeech(kids.get(i)) : ''; }
    function kidText(i) { return i < n ? String(kids.get(i).text()).trim() : ''; }
    function all(sep) {
        var out = [];
        for (var i = 0; i < n; i++) {
            var s = mathSpeech(kids.get(i));
            if (s) out.push(s);
        }
        return out.join(sep);
    }
    switch (name) {
        case 'mi':
        case 'mn':
        case 'mo':
        case 'mtext':
            return speechWord(text);
        case 'msub':
            return kid(0) + ' sub ' + kid(1) + ' end sub';
        case 'msup':
