function cfBody(response) {
    try {
        if (response == null) return "";
        var body = response.body;
        if (body != null && typeof body !== "function") return String(body);
        if (typeof body === "function") return String(body.call(response));
    } catch (e) {}
    return typeof response === "string" ? String(response) : "";
}
function cfChallenge(body){
    var t=String(body||"").toLowerCase();
    if(t.indexOf("just a moment")>=0) return true;
    if(t.indexOf("performing security verification")>=0) return true;
    if(t.indexOf("verify you are human")>=0) return true;
    if(t.indexOf("enable javascript and cookies")>=0) return true;
    if(t.indexOf("cf-chl-")>=0 && (t.indexOf("challenge")>=0 || t.indexOf("verify")>=0)) return true;
    if(t.indexOf("access denied")>=0 && (t.indexOf("ray id")>=0 || t.indexOf("cloudflare")>=0)) return true;
    return false;
}
var cfResponse=result;
if(cfChallenge(cfBody(cfResponse))){
