// inject js
remove_selector=[
    'script',
    'noscript',
    'style',
    'nav',
    'aside','.eapps-countdown-timer-inner',
    '[style*="background-image"]',
    'img[src*="http"]',
   ]
if (document.querySelector('#translate-done')){
result = document.body.outerHTML
}else if (!document.querySelector('#translate-start'))
{
var myspan = document.createElement("span");
myspan.id = 'translate-start'
document.body.append(myspan)
html = document.querySelector('html')
html.removeAttribute("class")
html.removeAttribute("translate")

// 获取所有具有srcset属性的img元素
const imagesWithSrcset = document.querySelectorAll('img[srcset]');

// 遍历每个img元素，并替换其src属性为srcset属性
imagesWithSrcset.forEach(img => {
img.src = img.getAttribute('srcset');
});

for (css of remove_selector){
for (element of document.querySelectorAll(css)){
   element.parentNode.removeChild(element);
}
